"""Generated by `make publish`: tests that need what the public copy leaves out."""

import pytest

SKIPS = {
    'tests/test_labels_frozen.py::test_tag_exists_and_no_engine_before_it': 'the public copy has no git tags or history (labels-v1)',
    'tests/test_fixed_rule.py::test_the_real_document_holds_both_figures_and_the_ten_decisions_of_test_bnd_001': 'needs runs/, which the public copy does not carry',
    'tests/test_site_chatbots.py::test_answer_days_are_not_before_the_protocol_was_committed': 'the public copy has one commit and no history of docs/chatbots/protocol.md',
}


def pytest_collection_modifyitems(items):
    for item in items:
        reason = SKIPS.get(item.nodeid)
        if reason:
            item.add_marker(pytest.mark.skip(reason=reason))
